name: Merge Queue
on:
  pull_request:
    types:
      - opened
      - synchronize
      - reopened
      - labeled
      - unlabeled
  merge_group:
    types:
      - checks_requested

jobs:
  merge-queue:
    runs-on: ubuntu-latest
    steps:
      - name: Merge Queue Check
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request?.number || context.payload.merge_group?.head_sha;

            if (!prNumber) {
              core.setFailed('No pull request number found');
              return;
            }

            // Check if PR has merge queue label
            const labels = context.payload.pull_request?.labels || [];
            const hasMergeQueueLabel = labels.some(label => 
              label.name.toLowerCase().includes('merge queue') || 
              label.name.toLowerCase().includes('queue')
            );

            // Only proceed if PR has merge queue label or is part of merge group
            if (!hasMergeQueueLabel && !context.payload.merge_group) {
              core.info('PR does not have merge queue label, skipping merge queue processing');
              return;
            }

            // Get PR details
            const pr = await github.rest.pulls.get({
              owner,
              repo,
              pull_number: prNumber
            });

            // Check if PR is ready for merge
            const isReady = pr.data.mergeable && 
                           pr.data.state === 'open' &&
                           pr.data.statuses_url.includes('success');

            if (!isReady) {
              core.info('PR is not ready for merge');
              return;
            }

            // Check for conflicts
            const commits = await github.rest.pulls.listCommits({
              owner,
              repo,
              pull_number: prNumber
            });

            // Verify no conflicts in the PR
            if (commits.data.length > 0) {
              core.info(`PR has ${commits.data.length} commits`);
            }

            // Log PR information for debugging
            core.info(`Processing PR #${prNumber}: ${pr.data.title}`);
            core.info(`Base branch: ${pr.data.base.ref}`);
            core.info(`Head branch: ${pr.data.head.ref}`);

            // Add comment to PR about merge queue status
            await github.rest.issues.createComment({
              owner,
              repo,
              issue_number: prNumber,
              body: 'This PR is queued for merging. It will be merged automatically once tests pass and conflicts are resolved.'
            });
